// Registry of KITTI-style datasets shipped under public/datasets/.
// Each step picks the active entry via the `?dataset=<id>` URL query
// (see useDataset). The default is kitti05-mini, the self-contained
// fixture generated by scripts/gen-kitti-mini.ts.

export type CalibFormat = 'odometry' | 'raw';

export interface DatasetDef {
  id: string;
  label: string;
  /** Public URL prefix (served from public/datasets/<id>). */
  dir: string;
  /** Filename relative to `dir` that holds projection/intrinsic data. */
  calibFile: string;
  /** Which parser to use for `calibFile`. */
  calibFormat: CalibFormat;
  /** Inclusive frame range is [0, frameCount-1]. */
  frameCount: number;
  /**
   * Cap for steps that load every frame up-front (Step09/10/11/13).
   * Defaults to frameCount; reduce for large drives to keep the browser-side
   * pipeline (decode → LK → PnP/BA) within a reasonable budget.
   */
  analysisFrames: number;
  description?: string;
}

const DATASET_LIST = [
  {
    id: 'kitti05-mini',
    label: 'KITTI-05 mini (synthetic, 5 frames)',
    dir: '/datasets/kitti05-mini',
    calibFile: 'calib.txt',
    calibFormat: 'odometry',
    frameCount: 5,
    analysisFrames: 5,
    description: 'Self-contained fixture: real KITTI-05 P0..P3 + procedural stereo.',
  },
  {
    id: 'kitti-sample',
    label: 'KITTI raw sample (2011_09_26, 108 frames)',
    dir: '/datasets/kitti-sample',
    calibFile: 'calib_cam_to_cam.txt',
    calibFormat: 'raw',
    frameCount: 108,
    analysisFrames: 10,
    description:
      'Raw KITTI drive. Requires calib_cam_to_cam.txt (P_rect_0X) at the dataset root.',
  },
] as const satisfies readonly DatasetDef[];

export const DATASETS: Readonly<Record<string, DatasetDef>> = Object.fromEntries(
  DATASET_LIST.map((d) => [d.id, d as DatasetDef]),
);

export type DatasetId = (typeof DATASET_LIST)[number]['id'];

export const DEFAULT_DATASET_ID: DatasetId = 'kitti05-mini';

export const ALL_DATASETS: readonly DatasetDef[] = DATASET_LIST;

export function isDatasetId(id: string | null | undefined): id is DatasetId {
  return !!id && id in DATASETS;
}

export function getDataset(id: string | null | undefined): DatasetDef {
  return isDatasetId(id) ? DATASETS[id] : DATASETS[DEFAULT_DATASET_ID];
}
